head.script:
// 테스트 설명, 유효성 값 설정
//  ※ 본 샘플(_2)은 getGroupbyData 반환값의 filter / filterRegExp 필드 검증 전용 분리본.
//    이 두 필드는 groupbyZone=true 에서 D&D groupby 또는 Group Column 필터링 시에만 반환되므로
//    groupby() 옵션에 filter/filterRegExp 를 적용(=Group Column 필터링)한 뒤 반환값에 나타나는지 실측한다.
//    (기타 반환필드/jsonType/undefined/hideGroupbyZone 은 _1 담당)
scwin.tData = {
    "description" : "[gridView > M > getGroupbyData]<br/>적용된 GroupBy 정보를 반환합니다.",
    "validation" : [
        "반환값의 filter 는 groupbyZone=true 에서 D&D groupby 또는 Group Column 필터링 시에만 반환되는 필터 정보(Object)입니다.",
        "반환값의 filterRegExp 는 Group Column 필터링 시에만 반환되는 정규식 정보(Object)입니다.",
    ]
}



scwin.onpageload = async function () {
    // 공통 DataList(gdl_boolean 등) 생성
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행) — groupbyZone=true 고정
scwin.comp_init = async function () {
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 4컬럼(region/dept/grade/score) 그리드, groupbyZone=true. grade 컬럼에 Group Column 필터(A,B 만 통과)를 건 상태로 region 기준 groupby.\n[절차] (1) [groupby (필터 적용)] : grade 필터(filter/filterRegExp) 를 옵션으로 groupby 적용 (2) [getGroupbyData(true)] 로 반환의 filter/filterRegExp 확인. [groupby (필터 미적용)] 과 대비.\n[확인] 필터 적용 시 반환값에 filter(Object)/filterRegExp(Object) 가 포함되고, 필터 미적용 groupby 시에는 두 필드가 나타나지 않음(undefined)."', '', 'label1');

    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="grade" name="grade" dataType="text"></w2:column>';
    strDlt += '<w2:column id="score" name="score" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "region": "부산", "dept": "기획", "grade": "C", "score": 60 },
        { "region": "서울", "dept": "개발", "grade": "A", "score": 20 },
        { "region": "서울", "dept": "영업", "grade": "B", "score": 40 },
        { "region": "부산", "dept": "영업", "grade": "B", "score": 50 },
        { "region": "서울", "dept": "개발", "grade": "A", "score": 10 },
        { "region": "서울", "dept": "개발", "grade": "A", "score": 30 }
    ];
    dlt_bind.setJSON(jsonData, false);

    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' groupbyZone="true" defaultCellHeight="28" dataList="data:dlt_bind" id="" style="width:600px;height:560px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getGroupbyData filter/filterRegExp 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol1" value="region(0)"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol2" value="dept(1)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol3" value="grade(2)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="score(3)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="region" dataList="region"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="grade" dataList="grade"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="score" dataList="score"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
};



// groupby (Group Column 필터 적용) : grade 컬럼에 filter/filterRegExp(A,B 만 통과) 를 옵션으로 적용
//  - filter : grade 를 배열["A","B"] 로 필터, filterRegExp : grade 를 정규식으로 필터
//  - 두 옵션은 groupbyStatus.groupbyOptions 에 그대로 직렬화되어 getGroupbyData 반환에 포함됨
scwin.btn_groupbyFilter_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");

    let options = {
        sortIndex: [0],
        sortOrder: [1],
        groupbyHeader: [
            { inputType: "expression", expression: "toggle() + depthStr()", colSpan: 4, align: "left" }
        ],
        hideFooter: true,
        // Group Column 필터링 : grade 값이 A 또는 B 인 행만 통과 (C 제외)
        filter: { grade: ["A", "B"] },
        filterRegExp: { grade: /^A$|^B$/gi }
    };

    if (target1.groupbyStatus && target1.groupbyStatus.grouped) {
        target1.clearGroupby();
    }
    target1.groupby(options);

    b.setReturnValue("[groupby (필터 적용)] region 기준 groupby + grade Group Column 필터(A,B) 적용. 이제 [getGroupbyData(true)] 로 filter/filterRegExp 반환을 확인하세요.");
};



// groupby (필터 미적용) : filter/filterRegExp 없이 groupby → 반환에 두 필드 미포함(대비용)
scwin.btn_groupbyPlain_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");

    let options = {
        sortIndex: [0],
        sortOrder: [1],
        groupbyHeader: [
            { inputType: "expression", expression: "toggle() + depthStr()", colSpan: 4, align: "left" }
        ],
        hideFooter: true
    };

    if (target1.groupbyStatus && target1.groupbyStatus.grouped) {
        target1.clearGroupby();
    }
    target1.groupby(options);

    b.setReturnValue("[groupby (필터 미적용)] region 기준 groupby 만 적용(필터 없음). [getGroupbyData(true)] 로 filter/filterRegExp 가 반환되지 않음(undefined)을 확인하세요.");
};



// getGroupbyData(true) : 반환 객체의 filter / filterRegExp 필드 실측
scwin.btn_getObject_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");

    let data = target1.getGroupbyData(true);
    if (typeof data === "undefined") {
        b.setReturnValue("[getGroupbyData(true)] 반환값 = undefined (먼저 groupby 를 적용하세요)");
        return;
    }

    let hasFilter = (typeof data.filter !== "undefined");
    let hasFilterRegExp = (typeof data.filterRegExp !== "undefined");

    b.setReturnValue("[getGroupbyData(true) — filter/filterRegExp]"
        + "\n filter 반환 여부=" + hasFilter + " (type=" + (hasFilter ? typeof data.filter : "-") + ") value=" + JSON.stringify(data.filter)
        + "\n filterRegExp 반환 여부=" + hasFilterRegExp + " (type=" + (hasFilterRegExp ? typeof data.filterRegExp : "-") + ") value=" + JSON.stringify(data.filterRegExp));
};
